PAGES=[page('089_page_1.jpg',169,[heading('Basic properties of the definite integrals'),paragraph('In computations involving integrals, it is often helpful to use the seven basic properties related to fundamental theorem of calculus that are listed below:'),heading('i.'),eq(r'\int_a^af(x)\,dx=0'),heading('Proof'),paragraph('By the definition of the definite integral'),eq(r'\int_a^af(x)\,dx=\lim_{n\to\infty}\sum_{i=1}^nf(x_i)\Delta x=\lim_{n\to\infty}\sum_{i=1}^nf(x_i)(0)'),eq(r'\Delta x=\frac{a-a}n=0'),eq(r'=\lim_{n\to\infty}(0)=0,\quad\mathrm{hence}\quad\int_a^af(x)\,dx=0'),heading('Challenge'),paragraph(r'Show that \(\int_a^af(x)\,dx=0\) by using fundamental theorem of integral calculus.'),heading('ii.'),eq(r'\int_a^bf(x)\,dx=\int_a^bf(y)\,dy'),heading('Proof'),paragraph('Let F(x) = f(x), [a,b] be an interval then by the fundamental theorem of integral calculus.'),eq(r'\int_a^bf(x)\,dx=F(b)-F(a)','i'),paragraph('also,'),eq(r'\int_a^bf(y)\,dy=F(b)-F(a)','ii'),paragraph('Hence, by (i) and (ii)'),eq(r'\int_a^bf(x)\,dx=\int_a^bf(y)\,dy\quad\mathrm{(proved)}'),heading('Challenge'),paragraph(r'Show that \(\int_a^bf(x)\,dx=\int_a^bf(y)\,dy\) by using the definition of definite integral.'),heading('iii.'),eq(r'\int_a^bf(x)\,dx=-\int_b^af(x)\,dx'),heading('Proof'),paragraph('By using the definition of definite integrate'),eq(r'\int_a^bf(x)\,dx=\lim_{n\to\infty}\sum_{i=1}^nf(x_i)'),paragraph('and'),eq(r'\int_b^af(x)\,dx=\lim_{n\to\infty}\sum_{i=1}^nf(x_i)\Delta x,\quad\Delta x=\frac{a-b}n'),eq(r'=\lim_{n\to\infty}\sum_{i=1}^nf(x_i)\frac{a-b}n=\lim_{n\to\infty}\left[-\sum_{i=1}^nf(x_i)\frac{b-a}n\right]'),eq(r'=-\lim_{n\to\infty}\sum_{i=1}^nf(x_i)\frac{b-a}n=-\int_a^bf(x)\,dx'),paragraph('Hence,'),eq(r'\int_a^bf(x)\,dx=-\int_b^af(x)\,dx'),heading('Challenge'),paragraph(r'Use fundamental theorem of integral calculus to show that \(\int_a^bf(x)\,dx=-\int_b^af(x)\,dx\).'),heading('iv.'),eq(r'\int_a^bf(x)\,dx=\int_a^cf(x)\,dx+\int_c^bf(x)\,dx,\quad a<c<b'),heading('Proof'),paragraph('Let F′(x) = f(x),a ≤ x ≤ b. By using the fundamental theorem of integral calculus.'),eq(r'\int_a^bf(x)\,dx=F(b)-F(a)'),paragraph('where f is continuous on [a,b] then'),note('Property (ii) needs F′(x) = f(x), not the printed F(x) = f(x). The first sum in the proof of (iii) omits Δx; a Riemann sum needs that factor. Reversing an interval also changes which samples are left/right endpoints, but their limits agree for a continuous function. The source introductory claim of seven properties is preserved; the displayed enumeration here runs i–v, with even/odd subcases in v.')
]),page('089_page_2.jpg',170,[heading('Property iv — proof continued'),eq(r'\int_a^cf(x)\,dx=F(c)-F(a)','i'),eq(r'\int_c^bf(x)\,dx=F(b)-F(c)','ii'),paragraph('By adding (i) and (ii)'),eq(r'\int_a^cf(x)\,dx+\int_c^bf(x)\,dx=F(c)-F(a)+F(b)-F(c)=F(b)-F(a)=\int_a^bf(x)\,dx'),paragraph('Hence,'),eq(r'\int_a^bf(x)\,dx=\int_a^cf(x)\,dx+\int_c^bf(x)\,dx'),heading('Challenge'),paragraph(r'Use definition of the definite integral to show that \(\int_a^bf(x)\,dx=\int_a^cf(x)\,dx+\int_c^bf(x)\,dx\).'),heading('v.'),eq(r'\int_{-a}^af(x)\,dx=2\int_0^af(x)\,dx\quad\mathrm{when}\quad f(-x)=f(x)'),eq(r'\int_{-a}^af(x)\,dx=0\quad\mathrm{when}\quad f(-x)=-f(x)'),heading('Proof'),paragraph('If f(x) is integral on interval [−a,a] w.r.t “x”, then for a number 0 in the interval [−a,a], the definite integral of f(x) from −a to a is 2 times the definite integral of f(x) from 0 to a:'),eq(r'\int_{-a}^af(x)\,dx=\int_{-a}^0f(x)\,dx+\int_0^af(x)\,dx=\int_a^0f(-x)\,d(-x)+\int_0^af(x)\,dx'),eq(r'=-\int_a^0f(-x)\,dx+\int_0^af(x)\,dx=\int_0^af(-x)\,dx+\int_0^af(x)\,dx'),eq(r'=\int_0^a[f(-x)+f(x)]\,dx'),eq(r'=2\int_0^af(x)\,dx\quad\mathrm{when}\quad f(-x)=f(x)'),eq(r'=0\quad\mathrm{when}\quad f(-x)=-f(x)'),note('The proof’s opening “2 times” sentence applies only to an even function. For an odd function the symmetric signed integral is zero. Integrability across the whole interval is essential; a pole at 0 is not made integrable by symmetry.'),heading('6.6.3 Extend techniques of integration using properties to calculate definite integral'),heading('Example 16'),paragraph('Evaluate the following definite integrals:'),eq(r'\mathrm{(a)}\quad\int_1^2(2x^2+4x+1)\,dx'),eq(r'\mathrm{(b)}\quad\int_1^2(2x^2+4x+1)\,dx=\int_1^2(2y^2+4y+1)\,dy'),eq(r'\mathrm{(c)}\quad\int_0^2(x^2+1)\,dx=-\int_2^0(x^2+1)\,dx'),eq(r'\mathrm{(d)}\quad\int_0^2(x^2+1)\,dx=\int_0^1(x^2+1)\,dx+\int_1^2(x^2+1)\,dx'),eq(r'\mathrm{(e)}\quad\int_{-1}^1x^2\,dx=\int_{-1}^0x^2\,dx+\int_0^1x^2\,dx=2\int_0^1x^2\,dx'),heading('Solution'),eq(r'\mathrm{a.}\quad\int_1^2(2x^2+4x+1)\,dx=\left[\frac{2x^3}3+\frac{4x^2}2+x\right]_1^2'),eq(r'=(\frac{16}3+\frac{16}2+2)-(\frac23+\frac42+1)=\frac{92}6-\frac{11}3=\frac{70}6=\frac{35}3'),eq(r'\mathrm{b.}\quad\int_1^2(2x^2+4x+1)\,dx=\int_1^2(2y^2+4y+1)\,dy'),eq(r'\left[\frac{2x^3}3+\frac{4x^2}2+x\right]_1^2=\left[\frac{2y^3}3+\frac{4y^2}2+y\right]_1^2\Rightarrow\frac{35}3=\frac{35}3,\quad\mathrm{since}\quad f(x)=g(y)'),eq(r'\mathrm{c.}\quad\int_0^2(x^2+1)\,dx=-\int_2^0(x^2+1)\,dx')])]
